class CardNimCustomStrategy:
    def __init__(self, model: BaseStrategy):
        self._model = model
        self.name = self._model.name
        self.history = self._model.history
        self.strategy_type = StrategyType.Custom

    def update_model_field(self, field_name: str, value: Any):
        if hasattr(self._model, field_name):
            setattr(self._model, field_name, value)

    def receive_message(self, message: Info) -> Info:
        cards, stones, opponent_card_played = message.message[0].data
        chosen_card = None

        # Calculate the GCD of the remaining cards
        def gcd(a, b):
            while b:
                a, b = b, a % b
            return a

        def gcd_list(numbers):
            result = numbers[0]
            for num in numbers[1:]:
                result = gcd(result, num)
            return result

        gcd_cards = gcd_list(cards)

        # Iterate over the remaining cards and calculate the number of stones that would be left after playing each card
        for card in cards:
            if card <= stones:
                stones_left = stones - card
                # Check if the number of stones left is a multiple of the GCD
                if stones_left % gcd_cards == 0:
                    chosen_card = card
                    break

        # If no such card is found, play the smallest card that is less than or equal to the number of stones
        if chosen_card is None:
            chosen_card = min([card for card in cards if card <= stones])

        return Info(
            sender=self.__class__.__name__,
            receiver=message.sender,
            difficulty=message.difficulty,
            message=[BaseMessageDataType(data=chosen_card, type='custom')]
        )

