        self.history = self._model.history
        self.strategy_type = StrategyType.Custom

    def update_model_field(self, field_name: str, value: Any):
        if hasattr(self._model, field_name):
            setattr(self._model, field_name, value)

    def minimax(self, cards, stones, depth, is_maximizing):
        if stones == 0:
            return -1 if is_maximizing else 1
        if not cards:
            return -1 if is_maximizing else 1

        if is_maximizing:
            best_score = -float('inf')
            for card in cards:
                if card <= stones:
                    new_cards = [c for c in cards if c!= card]
                    score = self.minimax(new_cards, stones - card, depth + 1, False)
                    best_score = max(score, best_score)
            return best_score
        else:
            best_score = float('inf')
            for card in cards:
                if card <= stones:
                    new_cards = [c for c in cards if c!= card]
                    score = self.minimax(new_cards, stones - card, depth + 1, True)
                    best_score = min(score, best_score)
            return best_score

    def receive_message(self, message: Info) -> Info:
        cards, stones, opponent_card_played = message.message[0].data
        playable_cards = [card for card in cards if card <= stones]

        if not playable_cards:
            return Info(
                sender=self.__class__.__name__,
                receiver=message.sender,
                difficulty=message.difficulty,
                message=[BaseMessageDataType(data=None, type='custom')]
            )

        best_card = max(playable_cards, key=lambda card: self.minimax([c for c in cards if c!= card], stones - card, 0, False))
        return Info(
            sender=self.__class__.__name__,
